import { jest } from '@jest/globals';

describe('GetHeroesUseCase', () => {
  let useCase: GetHeroesUseCase;
  let repository: jest.Mocked<HeroRepository>;

  beforeEach(() => {
    repository = jest.mocked({
      getHeroes: jest.fn().mockResolvedValue([]),
    }) as jest.Mocked<HeroRepository>;
    useCase = new GetHeroesUseCase(repository);
  });

  it('returns heroes from the repository', async () => {
    const heroes = [{ id: 1, name: 'Anti-Mage' }];
    repository.getHeroes.mockResolvedValue(heroes);

    await expect(useCase.execute()).resolves.toBe(heroes);
  });

  it('rejects when the repository rejects', async () => {
    const error = new Error('Repository error');
    repository.getHeroes.mockRejectedValue(error);

    await expect(useCase.execute()).rejects.toThrowError(error);
  });
});
```

